# Kaggle TPU v5e-8 kernel: runs a list of training jobs, one process per TPU chip. Generated by experiments/make_kernel.py.
# Before the jobs it finds out how to pin one process to one chip: it tries environment recipes, each by starting 8 tiny
# torch_xla processes at once; the first recipe where all 8 succeed is used. If none works, it tries torch_xla.launch
# (mhc_lab.xla_pool: one process per chip, jobs run in-process). If that fails too, jobs run one at a time on the whole host.
import json
import os
import signal
import subprocess
import sys
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

SOURCES = {}  # filled in by make_kernel.py: relative path -> file content
JOBS = []  # filled in by make_kernel.py: list of {"name": ..., "args": [...]}
TRAIN_SHARDS = 0  # filled in by make_kernel.py
DEADLINE_SECONDS = 0  # filled in by make_kernel.py: no job starts after this
HARD_STOP_SECONDS = DEADLINE_SECONDS + 3600  # every child process is killed and the kernel exits at this point (Kaggle's TPU limit is 9 h)
JOB_TIMEOUT_SECONDS = 3 * 3600  # one training job is killed after this
FIRST_STEP_TIMEOUT_SECONDS = 1800  # a job that has not logged its first step by then is killed (XLA compilation that never ends)
# Job keys besides name/args: "first_step_timeout" and "timeout" (seconds, override the two above); "expected_seconds" (how
# long the job should take; the start guard uses it instead of the longest job so far); "gate_min_tok_s": if that job ends
# without reaching this throughput, no further job starts (the implementation is too slow to be worth the quota);
# "only_if_failed": the name of another job; this one is a fallback that runs only if that job ended without exit 0.

START = time.time()
SRC = Path("/tmp/src")
DATA = Path("/tmp/data")
OUT = Path("/kaggle/working")
CHIPS = 8


def log(*parts) -> None:
    print(f"[{time.time() - START:7.1f}s]", *parts, flush=True)


def sh(cmd: str, timeout: int = 300) -> str:
    try:
        result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=timeout)
        return result.stdout + result.stderr
    except subprocess.TimeoutExpired:
        return f"TIMEOUT {cmd}"


log(sh("pip list 2>/dev/null | grep -i -E '^(torch|torch.xla|torch_xla|jax|jaxlib|libtpu|numpy) '"))
log(sh("env | grep -i -E '^(TPU|PJRT|XLA)' | grep -v -i token; nproc; free -g | head -2"))

for rel, content in SOURCES.items():
    path = SRC / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)

sys.path.insert(0, str(SRC))
from mhc_lab.data import REPO_URL  # noqa: E402

import urllib.request  # noqa: E402

DATA.mkdir(parents=True, exist_ok=True)
names = [f"train_{i:05d}.npy" for i in range(TRAIN_SHARDS)] + ["validation_00000.npy"]


def fetch(name: str) -> None:
    for attempt in range(5):
        try:
            partial = DATA / (name + ".part")
            urllib.request.urlretrieve(f"{REPO_URL}/{name}", partial)
            partial.rename(DATA / name)
            return
        except Exception as error:  # retry transient network errors
            log(f"retry {name}: {error}")
            time.sleep(5 * (attempt + 1))
    raise RuntimeError(f"could not download {name}")


with ThreadPoolExecutor(8) as pool:
    list(pool.map(fetch, names))
log(f"downloaded {len(names)} shards")


def recipe_env(name: str, chip: int) -> dict:
    port = 8476 + chip
    single = {"TPU_CHIPS_PER_PROCESS_BOUNDS": "1,1,1", "TPU_PROCESS_BOUNDS": "1,1,1", "TPU_RUNTIME_METRICS_PORTS": str(8431 + chip)}
    if name == "visible_chips":
        return {**single, "TPU_VISIBLE_CHIPS": str(chip), "TPU_PROCESS_PORT": str(port),
                "TPU_PROCESS_ADDRESSES": f"localhost:{port}", "CLOUD_TPU_TASK_ID": "0"}
    if name == "visible_chips_host_bounds":
        return {**recipe_env("visible_chips", chip), "TPU_CHIPS_PER_HOST_BOUNDS": "1,1,1", "TPU_HOST_BOUNDS": "1,1,1"}
    if name == "visible_devices_mesh":
        return {**single, "TPU_VISIBLE_DEVICES": str(chip), "TPU_MESH_CONTROLLER_ADDRESS": f"localhost:{port}",
                "TPU_MESH_CONTROLLER_PORT": str(port)}
    raise ValueError(name)


SMOKE = (
    "import time, torch, torch_xla, torch_xla.runtime as xr\n"
    "dev = torch_xla.device()\n"
    "a = torch.randn(4096, 4096, device=dev, dtype=torch.bfloat16)\n"
    "c = a @ a; torch_xla.sync(); c.cpu()\n"
    "t = time.time()\n"
    "for _ in range(20): c = a @ a\n"
    "torch_xla.sync(); c.cpu()\n"
    "dt = time.time() - t\n"
    "print('SMOKE devices', xr.global_runtime_device_count(), 'tflops', round(20 * 2 * 4096**3 / dt / 1e12, 1))\n"
)


def clear_tpu_locks() -> None:
    # libtpu leaves a lock file; a killed process can leave it behind and block the next one
    for path in ("/tmp/libtpu_lockfile",):
        if os.path.exists(path):
            os.remove(path)
            log(f"removed {path}")


def try_recipe(name: str) -> bool:
    clear_tpu_locks()
    procs = []
    for chip in range(CHIPS):
        env = {**os.environ, "PJRT_DEVICE": "TPU", **recipe_env(name, chip)}
        procs.append(subprocess.Popen([sys.executable, "-c", SMOKE], env=env, stdout=subprocess.PIPE,
                                      stderr=subprocess.STDOUT, text=True))
    ok = 0
    began = time.time()
    for chip, proc in enumerate(procs):
        try:
            out, _ = proc.communicate(timeout=max(1.0, 300 - (time.time() - began)))  # one shared 300 s budget for all 8
        except subprocess.TimeoutExpired:
            proc.kill()
            proc.communicate()
            out = "TIMEOUT"
        smoke = [line for line in out.splitlines() if line.startswith("SMOKE")]
        good = proc.returncode == 0 and smoke and smoke[0].split()[2] == "1"
        ok += bool(good)
        log(f"recipe {name} chip {chip}: rc {proc.returncode} {smoke[0] if smoke else out[-600:]}")
    return ok == CHIPS


def try_pool() -> bool:
    """Fallback: torch_xla.launch, one process per chip (mhc_lab.xla_pool)."""
    clear_tpu_locks()
    env = {**os.environ, "PJRT_DEVICE": "TPU", "PYTHONPATH": str(SRC)}
    cmd = [sys.executable, "-m", "mhc_lab.xla_pool", str(JOBS_PATH), str(OUT), str(DATA), str(START + DEADLINE_SECONDS), "--smoke"]
    try:
        result = subprocess.run(cmd, env=env, capture_output=True, text=True, timeout=600)
        out = result.stdout + result.stderr
    except subprocess.TimeoutExpired:
        out = "TIMEOUT"
    smoke = [line for line in out.splitlines() if line.startswith("SMOKE")]
    for line in smoke:
        log(f"pool {line}")
    if not smoke:
        log(f"pool smoke failed: {out[-1500:]}")
    return len({line.split()[2] for line in smoke}) == CHIPS


def try_single() -> bool:
    """The whole host in one process, no pinning: does the TPU work at all?"""
    clear_tpu_locks()
    env = {**os.environ, "PJRT_DEVICE": "TPU"}
    try:
        result = subprocess.run([sys.executable, "-c", SMOKE], env=env, capture_output=True, text=True, timeout=300)
        out = result.stdout + result.stderr
    except subprocess.TimeoutExpired:
        out = "TIMEOUT"
    smoke = [line for line in out.splitlines() if line.startswith("SMOKE")]
    log(f"single process: {smoke[0] if smoke else out[-1500:]}")
    return bool(smoke)


def descendants(root: int) -> list[int]:
    """Every process below root in the parent-pid tree (Linux /proc)."""
    children = {}
    for entry in os.listdir("/proc"):
        if not entry.isdigit():
            continue
        try:
            stat = Path(f"/proc/{entry}/stat").read_text()
        except OSError:
            continue
        ppid = int(stat.rsplit(")", 1)[1].split()[1])  # field 4; the command name in field 2 may contain spaces
        children.setdefault(ppid, []).append(int(entry))
    found = []
    stack = [root]
    while stack:
        for child in children.get(stack.pop(), []):
            found.append(child)
            stack.append(child)
    return found


def kill_descendants() -> None:
    """SIGTERM, then SIGKILL, every process this launcher started (directly or not)."""
    for sig in (signal.SIGTERM, signal.SIGKILL):
        for pid in descendants(os.getpid()):
            try:
                os.kill(pid, sig)
            except (ProcessLookupError, PermissionError):
                pass
        time.sleep(5)


def watchdog() -> None:
    """At HARD_STOP_SECONDS kill everything this kernel started and exit, so a hung job cannot burn the session's quota."""
    time.sleep(max(0.0, START + HARD_STOP_SECONDS - time.time()))
    log("hard stop: killing all child processes")
    (OUT / "hard_stop.txt").write_text(f"hard stop at {time.time() - START:.0f}s")
    kill_descendants()
    os._exit(0)


threading.Thread(target=watchdog, daemon=True).start()
(OUT / "single.json").write_text(json.dumps({"single_process_ok": try_single()}))

JOBS_PATH = Path("/tmp/jobs.json")
JOBS_PATH.write_text(json.dumps(JOBS))
recipe = None
for name in ("visible_chips", "visible_chips_host_bounds", "visible_devices_mesh"):
    if try_recipe(name):
        recipe = name
        break
if recipe is None and try_pool():
    recipe = "xla_pool"
log(f"per-chip recipe: {recipe}")
(OUT / "recipe.json").write_text(json.dumps({"recipe": recipe}))

if recipe == "xla_pool":
    env = {**os.environ, "PJRT_DEVICE": "TPU", "PYTHONPATH": str(SRC)}
    cmd = [sys.executable, "-m", "mhc_lab.xla_pool", str(JOBS_PATH), str(OUT), str(DATA), str(START + DEADLINE_SECONDS)]
    clear_tpu_locks()
    with open(OUT / "pool_log.txt", "w") as pool_out:
        try:
            code = subprocess.run(cmd, env=env, stdout=pool_out, stderr=subprocess.STDOUT,
                                  timeout=max(60.0, START + HARD_STOP_SECONDS - 300 - time.time())).returncode
        except subprocess.TimeoutExpired:
            code = "timeout"
    status = {}
    for job in JOBS:
        claim_file = OUT / "claims" / job["name"]
        status[job["name"]] = claim_file.read_text() if claim_file.exists() else "not run"
        status[job["name"]] = status[job["name"]] or "started, did not finish"
    (OUT / "status.json").write_text(json.dumps(status, indent=1))
    log(f"pool exit {code}; all done")
    sys.exit(0)

queue = list(JOBS)
lock = threading.Lock()
status = {}
longest = [0.0]  # longest job so far: a job is only started if one that long still ends before the hard stop


def run_job(job: dict, run_dir: Path, cmd: list, env: dict, began: float) -> str:
    """Run one job, killing it if it never logs a first step or runs past the job timeout. Returns its exit status."""
    first_step_timeout = job.get("first_step_timeout", FIRST_STEP_TIMEOUT_SECONDS)
    metrics = run_dir / "metrics.jsonl"
    with open(run_dir / "log.txt", "w") as out:
        proc = subprocess.Popen(cmd, env=env, stdout=out, stderr=subprocess.STDOUT)
        while proc.poll() is None:
            time.sleep(10)
            age = time.time() - began
            no_step = not metrics.exists() or metrics.stat().st_size == 0
            if proc.poll() is None and no_step and age > first_step_timeout:
                proc.kill()
                proc.wait()
                return f"killed: no first step after {first_step_timeout}s"
            if proc.poll() is None and age > job.get("timeout", JOB_TIMEOUT_SECONDS):
                proc.kill()
                proc.wait()
                return "killed: job timeout"
    return f"exit {proc.returncode}"


def gate_passed(job: dict, run_dir: Path) -> bool:
    summary = run_dir / "summary.json"
    tok_s = json.loads(summary.read_text()).get("tok_s") if summary.exists() else None
    log(f"gate {job['name']}: tok/s {tok_s}, needs {job['gate_min_tok_s']}")
    return tok_s is not None and tok_s >= job["gate_min_tok_s"]


def worker(chip: int) -> None:
    while True:
        with lock:
            if not queue:
                return
            for job in [j for j in queue if status.get(j.get("only_if_failed"), "").startswith("exit 0")]:
                status[job["name"]] = f"skipped ({job['only_if_failed']} succeeded)"
                queue.remove(job)
            waiting = [j for j in queue if j.get("only_if_failed") and j["only_if_failed"] not in status]
            elapsed = time.time() - START
            fits = [j for j in queue if j not in waiting
                    and elapsed + j.get("expected_seconds", longest[0]) < HARD_STOP_SECONDS - 600]
            if elapsed > DEADLINE_SECONDS or not (fits or waiting):
                for job in queue:
                    status[job["name"]] = "skipped (deadline)"
                queue.clear()
                return
            if not fits:
                return  # only fallbacks of running jobs are left: the chip a failed job frees will take its fallback
            job = fits[0]  # the first job in the queue that can still end before the hard stop
            queue.remove(job)
        began = time.time()
        run_dir = OUT / "runs" / job["name"]
        run_dir.mkdir(parents=True, exist_ok=True)
        module = job.get("module", "mhc_lab.train_xla")
        cmd = [sys.executable, "-m", module, "--out", str(run_dir), "--data-dir", str(DATA), *job["args"]]
        env = {**os.environ, "PJRT_DEVICE": "TPU", "PYTHONPATH": str(SRC)}
        if recipe is not None:
            env.update(recipe_env(recipe, chip))
        code = run_job(job, run_dir, cmd, env, began)
        took = time.time() - began
        with lock:
            longest[0] = max(longest[0], took)
            status[job["name"]] = f"{code} in {took:.0f}s on chip {chip}"
            log(f"{job['name']}: {status[job['name']]}")
            if code != "exit 0":  # the job's own log only comes back with the final download: show why it failed now
                tail = (run_dir / "log.txt").read_text(errors="replace").splitlines()[-12:]
                log("\n".join(line[:300] for line in tail))
            if "gate_min_tok_s" in job and not gate_passed(job, run_dir):
                log(f"gate {job['name']} failed: no further jobs start")
                for waiting in queue:
                    status[waiting["name"]] = f"skipped (gate {job['name']} failed)"
                queue.clear()
            (OUT / "status.json").write_text(json.dumps(status, indent=1))


workers = CHIPS if recipe is not None else 1
threads = [threading.Thread(target=worker, args=(c,)) for c in range(workers)]
for t in threads:
    t.start()
for t in threads:
    t.join()
for job in queue:
    status[job["name"]] = "skipped (not run)"
(OUT / "status.json").write_text(json.dumps(status, indent=1))
log("all done")
